# Cold-Start Router + Full-History Seen Filter + Production Eligibility Rules
retrieval_pos_counts = {15: 12, 42: 35, 24: 0}  # User 24 has 0 retrieval positives (COLD!)
full_seen_history = {
    15: {10, 20},
    24: {10, 30},  # User 24 still saw {10, 30} (e.g. low stars or ranker role) -> MUST filter!
}

# Item eligibility metadata (production business rules)
item_meta = {
    10: {"region_ok": True,  "in_stock": True,  "age_ok": True},
    20: {"region_ok": False, "in_stock": True,  "age_ok": True},  # Region blocked!
    30: {"region_ok": True,  "in_stock": True,  "age_ok": True},
    40: {"region_ok": True,  "in_stock": True,  "age_ok": False}, # Age restricted!
    50: {"region_ok": True,  "in_stock": True,  "age_ok": True},
    60: {"region_ok": True,  "in_stock": True,  "age_ok": True},
    70: {"region_ok": True,  "in_stock": False, "age_ok": True},  # Unavailable!
    80: {"region_ok": True,  "in_stock": True,  "age_ok": True},
}

pop_ranked_catalog = [10, 20, 30, 40, 50, 60, 70, 80]

def is_eligible(mid, seen_set):
    if mid in seen_set:
        return False
    m = item_meta[mid]
    return m["region_ok"] and m["in_stock"] and m["age_ok"]

def route_request(user_id, k=3):
    pos_cnt = retrieval_pos_counts.get(user_id, 0)
    seen = full_seen_history.get(user_id, set())
    if pos_cnt == 0:
        recs = []
        for mid in pop_ranked_catalog:
            if is_eligible(mid, seen):
                recs.append(mid)
                if len(recs) == k:
                    break
        return "popularity_fallback", recs
    return "neural_two_stage_pipeline", []

for uid in [15, 24, 999]:
    route, recs = route_request(uid, k=3)
    print(f"User {uid:3d} (ret_pos={retrieval_pos_counts.get(uid, 0):2d}) -> {route:25s} | recs={recs}")

candidates = {"A": (.20, .02, .001), "B": (.10, .08, .003)}
def utility(ctr, purchase_given_click, complaint_per_impression):
    purchase_per_impression = ctr * purchase_given_click
    return 40 * purchase_per_impression - 10 * complaint_per_impression

scores = {name: utility(*probabilities) for name, probabilities in candidates.items()}
assert max(candidates, key=lambda name: candidates[name][0]) == "A"
assert max(scores, key=scores.get) == "B"
print(scores["A"], scores["B"])
